from solution import allocate


def ref(total, weights):
    s = sum(weights)
    if s == 0:
        raise ValueError
    sign = -1 if total < 0 else 1
    t = abs(total)
    base = [t * w // s for w in weights]
    rem = [(t * w) % s for w in weights]
    left = t - sum(base)
    order = sorted(range(len(weights)), key=lambda i: (-rem[i], i))
    for i in order[:left]:
        base[i] += 1
    return [sign * b for b in base]


def test_examples():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_large_precision():
    w = [1, 3, 7, 11]
    t = 10**18 + 7
    assert allocate(t, w) == ref(t, w)


def test_large_ties():
    t = 10**17 + 1
    w = [1, 1, 1]
    assert allocate(t, w) == ref(t, w)


def test_near_ties_big():
    t = 9007199254740993
    w = [3, 3, 3, 1]
    assert allocate(t, w) == ref(t, w)


def test_negative():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_zero_total():
    r = allocate(0, [1, 2])
    assert r == [0, 0]


def test_all_zero_raises():
    try:
        allocate(10, [0, 0])
        assert False
    except ValueError:
        pass


def test_empty_raises():
    try:
        allocate(10, [])
        assert False
    except ValueError:
        pass


def test_sum_preserved_random():
    import random
    random.seed(1)
    for _ in range(300):
        n = random.randint(1, 6)
        w = [random.randint(0, 10**random.randint(0, 12)) for _ in range(n)]
        if sum(w) == 0:
            continue
        t = random.randint(-10**15, 10**15)
        r = allocate(t, w)
        assert r == ref(t, w)
        assert sum(r) == t


def test_zero_weight_gets_zero():
    assert allocate(7, [0, 1, 0, 1]) == [0, 4, 0, 3]

from solution import allocate
import pytest


def test_examples():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(5, [1, 0, 1]) == [3, 0, 2]


def test_negative():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]
    assert allocate(-5, [1, 0, 1]) == [-3, 0, -2]


def test_all_zero_raises():
    with pytest.raises(ValueError):
        allocate(10, [0, 0])
    with pytest.raises(ValueError):
        allocate(0, [0])


def test_empty_weights():
    # all() of empty is True -> ValueError
    with pytest.raises(ValueError):
        allocate(5, [])


def test_zero_total():
    assert allocate(0, [1, 2, 3]) == [0, 0, 0]


def test_negative_zero_no_neg():
    r = allocate(0, [1, 1])
    assert r == [0, 0]


def test_remainder_ordering():
    # shares: 10*1/6=1.67, 10*2/6=3.33, 10*3/6=5 -> floors 1,3,5 leftover 1 -> to first
    assert allocate(10, [1, 2, 3]) == [2, 3, 5]


def test_ties_earlier():
    assert allocate(2, [1, 1, 1]) == [1, 1, 0]


def test_large_exact():
    t = 10**30 + 7
    r = allocate(t, [1, 1, 1])
    assert sum(r) == t
    assert max(r) - min(r) <= 1


def test_single_weight():
    assert allocate(7, [5]) == [7]
    assert allocate(-7, [0, 5]) == [0, -7]


def test_sum_property():
    for total in range(-30, 31):
        for ws in ([1, 2, 3], [0, 3, 0, 4], [7, 1, 1]):
            assert sum(allocate(total, ws)) == total
